import gzip
import os
import re
from datetime import date, timedelta, timezone

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?\Z")
_DATED = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")


class Archive:
    def __init__(self, old, key, gz, base=None, new=False):
        self.old = old          # file name before the run (None for the new archive)
        self.key = key          # age key: smaller is newer
        self.gz = gz
        self.base = base        # dated: name without .gz
        self.new = new
        self.time = None        # raw state time (as stored) or None
        self.when = None        # parsed
        self.final = None
        self.compress = False
        self.remove = False


def _age_key(naming, number=None, day=None, k=1):
    if naming == "numbered":
        return (number,)
    return (-day.toordinal(), -k)


def scan(data, name, naming):
    """The archives of a stream, newest first (rotate.md, section 2)."""
    d = streams.logs_dir(data)
    prefix = f"{name}.log."
    found = []
    places = set()
    if d.is_dir():
        for p in d.iterdir():
            if not p.name.startswith(prefix) or not p.is_file():
                continue
            rest = p.name[len(prefix):]
            if naming == "numbered":
                m = _NUMBERED.match(rest)
                if not m:
                    continue
                key = _age_key(naming, number=int(m.group(1)))
                arch = Archive(p.name, key, bool(m.group(2)))
            else:
                m = _DATED.match(rest)
                if not m:
                    continue
                try:
                    day = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
                except ValueError:
                    continue
                k = int(m.group(4)) if m.group(4) else 1
                key = _age_key(naming, day=day, k=k)
                arch = Archive(p.name, key, bool(m.group(5)), base=p.name[:-3] if m.group(5) else p.name)
            if key in places:
                raise DataError("archives", f"{name}: two archives in the same place")
            places.add(key)
            found.append(arch)
    found.sort(key=lambda a: a.key)
    return found


def _first_line_time(path):
    try:
        with open(path, "rb") as f:
            line = f.readline()
    except OSError:
        return None
    text = line.decode("utf-8", errors="replace").rstrip("\r\n")
    return dates.parse_aware(text.split(" ", 1)[0])


class StreamPlan:
    pass


def check_state(doc, existing):
    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        if "opened" in entry and dates.parse_state(entry["opened"]) is None:
            raise DataError("state", f"{name}: bad opened")
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for k, v in arch.items():
                if dates.parse_state(v) is None:
                    raise DataError("state", f"{name}: bad time for {k}")
        if "rotations" in entry:
            r = entry["rotations"]
            if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                raise DataError("state", f"{name}: rotations is not a whole number")


def _decide(ctx, name, st, entry, force, now):
    log = streams.log_path(ctx.data, name)
    if not log.is_file():
        return None, "no log"
    size = log.stat().st_size
    if size == 0:
        return None, "empty"
    if force:
        return "forced", "rotate (forced)"
    if st["max_size"] is not None and size >= st["max_size"]:
        return "size", "rotate (size)"
    if st["max_age"] is not None:
        opened = None
        if "opened" in entry:
            opened = dates.parse_state(entry["opened"])
        else:
            opened = _first_line_time(log)
        if opened is not None and now - opened >= st["max_age"]:
            return "age", "rotate (age)"
    return None, "not due"


def plan_stream(ctx, name, pol, doc):
    now = ctx.now
    st = policy.settings(pol, name)
    entry = doc["streams"].get(name, {})
    p = StreamPlan()
    p.name = name
    p.st = st
    p.entry = entry
    why, p.what = _decide(ctx, name, st, entry, ctx.force, now)
    p.rotated = why is not None
    p.archives = scan(ctx.data, name, st["naming"])
    times = entry.get("archives", {})
    for a in p.archives:
        if a.old in times:
            a.time = times[a.old]
            a.when = dates.parse_state(a.time)
    if p.rotated:
        if st["naming"] == "numbered":
            new = Archive(None, (0,), False, new=True)
            p.archives.insert(0, new)
        else:
            day = now.astimezone(timezone(st["offset"])).date()
            used = set()
            for a in p.archives:
                if a.key[0] == -day.toordinal():
                    used.add(-a.key[1])
            if not used:
                k = 1
            else:
                k = 2
                while k in used:
                    k += 1
            base = f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")
            new = Archive(None, _age_key("dated", day=day, k=k), False, base=base, new=True)
            p.archives.append(new)
            p.archives.sort(key=lambda a: a.key)
        new.time = dates.stamp(now)
        new.when = now
    # retention (positions counted before anything is removed)
    keep_days = st["keep_days"]
    for i, a in enumerate(p.archives, 1):
        if i > st["keep"]:
            a.remove = True
        elif keep_days is not None and a.when is not None and now - a.when >= timedelta(days=keep_days):
            a.remove = True
    p.remaining = [a for a in p.archives if not a.remove]
    p.removed = [a for a in p.archives if a.remove]
    for i, a in enumerate(p.remaining, 1):
        a.compress = (i > st["compress_after"]) and not a.gz
        gz = a.gz or a.compress
        if st["naming"] == "numbered":
            base = f"{name}.log.{i}"
        else:
            base = a.base
        a.final = base + (".gz" if gz else "")
    return p


def plan_lines(p):
    lines = [f"{p.name}: {p.what}"]
    for a in p.remaining:
        if a.new:
            lines.append(f"  new {a.final}")
        elif a.final != a.old:
            lines.append(f"  {a.final} <- {a.old}")
        else:
            lines.append(f"  {a.final}")
    for a in p.removed:
        lines.append(f"  remove {a.old}")
    return lines


def apply_stream(ctx, p):
    logs = streams.logs_dir(ctx.data)
    for a in p.removed:
        (logs / a.old).unlink()
    moves = []
    for i, a in enumerate(p.remaining):
        if not a.new and a.final == a.old:
            continue
        src = streams.log_path(ctx.data, p.name) if a.new else logs / a.old
        tmp = logs / f".{p.name}.rotate{i}.tmp"
        if a.compress:
            tmp.write_bytes(gzip.compress(src.read_bytes(), mtime=0))
            if a.new:
                src.write_bytes(b"")
            else:
                src.unlink()
        else:
            os.rename(src, tmp)
            if a.new:
                src.write_bytes(b"")
        moves.append((tmp, logs / a.final))
    for tmp, dst in moves:
        os.rename(tmp, dst)


def run(ctx, names, dry_run, force):
    """Returns the output lines. `names` is the list of streams named, or empty for all."""
    pol = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | set(pol["streams"])
    check_state(doc, existing)
    if names:
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
        todo = sorted(set(names))
    else:
        todo = sorted(existing)
    ctx.force = force
    plans = [plan_stream(ctx, n, pol, doc) for n in todo]
    out = []
    rotated = removed = compressed = 0
    for p in plans:
        out.extend(plan_lines(p))
        rotated += p.rotated
        removed += len(p.removed)
        compressed += sum(1 for a in p.remaining if a.compress)
    out.append(f"{rotated} rotated, {removed} removed, {compressed} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out
    for p in plans:
        apply_stream(ctx, p)
    for p in plans:
        entry = {}
        if p.rotated:
            entry["opened"] = dates.stamp(ctx.now)
        elif "opened" in p.entry:
            entry["opened"] = p.entry["opened"]
        entry["rotations"] = p.entry.get("rotations", 0) + (1 if p.rotated else 0)
        entry["archives"] = {a.final: a.time for a in p.remaining if a.time is not None}
        doc["streams"][p.name] = entry
    ctx.data.mkdir(parents=True, exist_ok=True)
    state.save(ctx.state_path, doc)
    return out
